#include <bits/stdc++.h>
#define sec second
#define fst first
#define fast_io ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr)
#define output(n) return cout << n, 0
#define set_prec(n) cout << fixed << setprecision(n)
#define push_back emplace_back
#define long long long
#define long_double long double
#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops")
using namespace std;

const int MAX_LIMIT = 1e6 + 100, INF_LIMIT = 1e9 + 7, MOD_LIMIT = 1e9 + 7, P_CONST = 6151, T_CONST = 2000, SQ_CONST = 280, LOG_SZ = 64, LOG2_SZ = 34;
typedef pair<int, int> pair_int;

int total_num, base_d;
vector<int> digits;

struct node {
    int mat[LOG2_SZ][LOG2_SZ], temp[LOG2_SZ][LOG2_SZ];
    bool visited[LOG2_SZ], toggled[LOG2_SZ];

    void combine(node &other) {
        for (int i = 0; i <= base_d; i++) {
            for (int j = 0; j <= base_d; j++) {
                mat[i][j] = 0;
                for (int k = 0; k <= base_d; k++)
                    mat[i][j] = (mat[i][j] + mat[k][j] * other.mat[i][k]) % MOD_LIMIT;
            }
        }
        for (int i = 0; i < base_d; i++) {
            if (visited[i] && !other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    mat[i][j] = mat[i][j];
            }
            if (!visited[i] && other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    mat[j][i] = other.mat[j][i];
            }
            visited[i] |= other.visited[i];
        }
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                mat[i][j] = mat[i][j];
    }

    void reset() {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                mat[i][j] = temp[i][j] = 0;
    }

    void shift(int shift_value) {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                temp[i][j] = 0;
        for (int i = 0; i < base_d; i++) {
            for (int j = 0; j < base_d; j++)
                temp[(i + shift_value) % base_d][(j + shift_value) % base_d] = mat[i][j];
            temp[(i + shift_value) % base_d][base_d] = mat[i][base_d];
        }
        for (int i = 0; i < base_d; i++)
            temp[base_d][(i + shift_value) % base_d] = mat[base_d][i];
        temp[base_d][base_d] = mat[base_d][base_d];

        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                mat[i][j] = temp[i][j];

        for (int i = 0; i < base_d; i++)
            toggled[i] = visited[(i + shift_value) % base_d];
        for (int i = 0; i < base_d; i++)
            visited[i] = toggled[i];
    }
} node_arr[LOG_SZ], helper_arr[LOG_SZ], temp_node_obj;

node fetch_node(int x) {
    int h = x, pw = 1, t_idx = -1;
    while (h >= base_d) {
        h /= base_d;
        pw *= base_d;
        t_idx++;
    }
    x %= pw;
    if (t_idx == -1)
        return helper_arr[h];
    node res_node = node_arr[t_idx];
    temp_node_obj = node_arr[t_idx];
    for (int i = 1; i < h; i++) {
        temp_node_obj.shift(1);
        res_node.combine(temp_node_obj);
    }
    temp_node_obj = node_arr[t_idx];
    temp_node_obj = fetch_node(x);
    temp_node_obj.shift(h);
    res_node.combine(temp_node_obj);
    return res_node;
}

int main() {
    fast_io;
    cin >> total_num >> base_d;
    total_num--;
    int temp_total = total_num;
    while (total_num) {
        digits.push_back(total_num % base_d);
        total_num /= base_d;
    }
    node_arr[0].mat[base_d][base_d] = 2;
    node_arr[0].mat[base_d][0] = -1;
    node_arr[0].mat[0][base_d] = 1;
    node_arr[0].visited[0] = true;
    for (int i = 1; i < base_d; i++) {
        node_arr[i].mat[base_d][base_d] = 2;
        node_arr[i].mat[base_d][i] = -1;
        node_arr[i].mat[i][base_d] = 1;
        node_arr[i].visited[i] = true;
        helper_arr[0].merge(node_arr[i]);
        node_arr[i] = helper_arr[0];
    }
    for (int i = 1; i <= (int)digits.size(); i++) {
        node_arr[i] = node_arr[i - 1];
        temp_node_obj = node_arr[i - 1];
        for (int j = 1; j < base_d; j++) {
            temp_node_obj.shift(1);
            helper_arr[i].merge(temp_node_obj);
        }
    }
    node final_result = fetch_node(temp_total);
    cout << final_result.mat[base_d][base_d] << "\n";
    return 0;
}
